def f(inputs):
    results = []
    for input in inputs:
        C, W = input[0], input[1]
        edges = input[2]
        adj = [[] for _ in range(C)]
        in_degree = [0] * C
        for x, y in edges:
            adj[x].append(y)
            in_degree[y] += 1
        topo = []
        q = [i for i in range(C) if in_degree[i] == 0]
        while q:
            start = q.pop(0)
            topo.append(start)
            for end in adj[start]:
                in_degree[end] -= 1
                if in_degree[end] == 0:
                    q.append(end)
        if len(topo)!= C:
            results.append("IMPOSSIBLE")
        else:
            answers = [0] * W
            q = [i for i in range(W) if (input[3][i][0] not in topo or input[3][i][1] not in topo)]
            while q:
                start = q.pop(0)
                for end in range(W-1, -1, -1):
                    if input[3][end][0] == topo[start]:
                        answers[end] = topo[start]
                        q.append(end - 1)
            questions = []
            q = [i for i in range(W) if input[3][i][0] in topo]
            while q:
                start = q.pop(0)
                for end in range(W-1, -1, -1):
                    if input[3][end][0] == topo[start] and topo[start] not in topo[start+1:]:
                        questions.append(input[3][end])
                        q.append(end - 1)
            results.append(" ".join(map(str, answers + questions)))
    return results

